\"\"\"Send private text prompts to the OpenAI Responses API.

Uses only the Python standard library. Prompts and responses are not written
to disk. Requests default to "'``store=false`` so the API does not persist the
generation for later retrieval. The API key is read from the environment or a
constructor argument and is never included in ``repr`` or error text.
"""

from __future__ import annotations

import json
import os
import urllib.error
import urllib.request
from typing import Any

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4.1-mini"
DEFAULT_TIMEOUT = 60.0
_MAX_ERROR_BYTES = 65536


class OpenAIError(Exception):
    """API or client failure that does not include the prompt."""

    def __init__(
        self,
        message: str,
        *,
        status: int | None = None,
        code: str | None = None,
    ) -> None:
        super().__init__(message)
        self.status = status
        self.code = code


class OpenAIRefusal(OpenAIError):
    """The model refused the prompt and returned no output text."""


class OpenAIClient:
    """Minimal Responses API client for private text prompts."""

    def __init__(
        self,
        api_key: str | None = None,
        *,
        base_url: str | None = None,
        model: str | None = None,
        timeout: float = DEFAULT_TIMEOUT,
        store: bool = False,
        organization: str | None = None,
        project: str | None = None,
    ) -> None:
        key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY")
        if not key or not str(key).strip():
            raise OpenAIError("Missing OpenAI API key. Set OPENAI_API_KEY.")
        self._api_key = str(key).strip()
        root = base_url if base_url is not None else os.environ.get(
            "OPENAI_BASE_URL", DEFAULT_BASE_URL
        )
        self.base_url = str(root).rstrip("/")
        self.model = model or os.environ.get("OPENAI_MODEL", DEFAULT_MODEL)
        self.timeout = timeout
        self.store = store
        self.organization = organization or os.environ.get("OPENAI_ORG_ID")
        self.project = project or os.environ.get("OPENAI_PROJECT_ID")

    def __repr__(self) -> str:
        return (
            f"OpenAIClient(base_url={self.base_url!r}, model={self.model!r}, "
            f"store={self.store!r})"
        )

    def create_response(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        temperature: float | None = None,
        store: bool | None = None,
        timeout: float | None = None,
    ) -> dict[str, Any]:
        """POST a text prompt to ``/responses`` and return the JSON object.

        ``store`` defaults to this client'"'s setting, which is false. Do not
        pass identifying metadata; this method only sends the text fields
        needed for a private generation.
        \"\"\"
        if not isinstance(prompt, str):
            raise OpenAIError(\"Prompt must be a string.\")
        if prompt == \"\":
            raise OpenAIError(\"Prompt must not be empty.\")

        payload: dict[str, Any] = {
            \"model\": model or self.model,
            \"input\": prompt,
            \"store\": self.store if store is None else store,
        }
        if instructions is not None:
            if not isinstance(instructions, str):
                raise OpenAIError(\"Instructions must be a string.\")
            payload[\"instructions\"] = instructions
        if max_output_tokens is not None:
            payload[\"max_output_tokens\"] = max_output_tokens
        if temperature is not None:
            payload[\"temperature\"] = temperature

        return self._post_json(\"/responses\", payload, timeout=timeout)

    def send_prompt(self, prompt: str, **kwargs: Any) -> str:
        \"\"\"Send a text prompt and return assistant output text.\"\"\"
        response = self.create_response(prompt, **kwargs)
        text = extract_output_text(response)
        if text:
            return text
        refusal = extract_refusal(response)
        if refusal:
            raise OpenAIRefusal(refusal)
        status = response.get(\"status\")
        raise OpenAIError(
            \"Response contained no output text.\"
            + (f\" status={status}\" if status else \"\")
        )

    def _post_json(
        self,
        path: str,
        payload: dict[str, Any],
        *,
        timeout: float | None,
    ) -> dict[str, Any]:
        body = json.dumps(payload, ensure_ascii=False).encode(\"utf-8\")
        request = urllib.request.Request(
            f\"{self.base_url}{path}\",
            data=body,
            headers=self._headers(),
            method=\"POST\",
        )
        try:
            with urllib.request.urlopen(
                request, timeout=self.timeout if timeout is None else timeout
            ) as response:
                raw = response.read()
        except urllib.error.HTTPError as exc:
            raise _error_from_http(exc) from None
        except urllib.error.URLError as exc:
            reason = getattr(exc, \"reason\", exc)
            raise OpenAIError(f\"Network error contacting OpenAI: {reason}\") from None

        try:
            parsed = json.loads(raw.decode(\"utf-8\"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise OpenAIError(\"OpenAI returned a non-JSON response.\") from None
        if not isinstance(parsed, dict):
            raise OpenAIError(\"OpenAI returned an unexpected response shape.\")
        return parsed

    def _headers(self) -> dict[str, str]:
        headers = {
            \"Authorization\": f\"Bearer {self._api_key}\",
            \"Content-Type\": \"application/json\",
            \"Accept\": \"application/json\",
        }
        if self.organization:
            headers[\"OpenAI-Organization\"] = self.organization
        if self.project:
            headers[\"OpenAI-Project\"] = self.project
        return headers


def extract_output_text(response: dict[str, Any]) -> str:
    \"\"\"Collect assistant text from a Responses API JSON object.\"\"\"
    direct = response.get(\"output_text\")
    if isinstance(direct, str) and direct:
        return direct
    chunks: list[str] = []
    output = response.get(\"output\")
    if not isinstance(output, list):
        return \"\"
    for item in output:
        if not isinstance(item, dict):
            continue
        if item.get(\"type\") == \"output_text\" and isinstance(item.get(\"text\"), str):
            chunks.append(item[\"text\"])
            continue
        content = item.get(\"content\")
        if not isinstance(content, list):
            continue
        for part in content:
            if not isinstance(part, dict):
                continue
            if part.get(\"type\") in {\"output_text\", \"text\"} and isinstance(
                part.get(\"text\"), str
            ):
                chunks.append(part[\"text\"])
    return \"\".join(chunks)


def extract_refusal(response: dict[str, Any]) -> str:
    \"\"\"Return concatenated refusal text, if the model refused.\"\"\"
    chunks: list[str] = []
    output = response.get(\"output\")
    if not isinstance(output, list):
        return \"\"
    for item in output:
        if not isinstance(item, dict):
            continue
        content = item.get(\"content\")
        if not isinstance(content, list):
            continue
        for part in content:
            if isinstance(part, dict) and part.get(\"type\") == \"refusal\":
                refusal = part.get(\"refusal\")
                if isinstance(refusal, str):
                    chunks.append(refusal)
    return \"\".join(chunks)


def send_prompt(prompt: str, **kwargs: Any) -> str:
    \"\"\"Send one private text prompt using environment credentials.\"\"\"
    client_kwargs = {}
    for name in (\"api_key\", \"base_url\", \"model\", \"timeout\", \"store\", \"organization\", \"project\"):
        if name in kwargs:
            client_kwargs[name] = kwargs.pop(name)
    return OpenAIClient(**client_kwargs).send_prompt(prompt, **kwargs)


def _error_from_http(exc: urllib.error.HTTPError) -> OpenAIError:
    status = getattr(exc, \"code\", None)
    raw = b\"\"
    try:
        raw = exc.read(_MAX_ERROR_BYTES)
    except Exception:
        raw = b\"\"
    message = f\"OpenAI request failed with HTTP {status}.\"
    code = None
    try:
        parsed = json.loads(raw.decode(\"utf-8\"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        parsed = None
    if isinstance(parsed, dict):
        error = parsed.get(\"error\")
        if isinstance(error, dict):
            api_message = error.get(\"message\")
            api_code = error.get(\"code\")
            if isinstance(api_message, str) and api_message.strip():
                message = api_message.strip()
            if isinstance(api_code, str) and api_code.strip():
                code = api_code.strip()
    return OpenAIError(message, status=status, code=code)


def main() -> int:
    import sys

    prompt = sys.stdin.read()
    if not prompt.strip():
        sys.stderr.write(\"Provide a text prompt on stdin.\\n\")
        return 2
    try:
        sys.stdout.write(send_prompt(prompt))
    except OpenAIError as exc:
        sys.stderr.write(f\"{exc}\\n\")
        return 1
    if not prompt.endswith(\"\\n\"):
        sys.stdout.write(\"\\n\")
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
